import type { CategoryId } from "./game-registry";

export interface GameMetadata {
  name: string;
  icon: string;
  color: string;
  description: string;
  category: CategoryId;
  madeByKid: boolean;
  /**
   * The module records gameplay clips (metadata literal clips: true). The
   * generator always writes it; it is optional so a hand-made lookup entry
   * (a test) can leave it out, which means false.
   */
  clips?: boolean;
  /**
   * The orientation the game plays best in on a phone (metadata literal
   * preferredOrientation). GameShell shows the orientation tip from it.
   * Absent for a game that plays well both ways.
   */
  preferredOrientation?: "portrait" | "landscape";
}

